insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"CLOSED_BOTH3","title":"¿Ambos anotan 3 o más y la diferencia es de 2 o menos?","description":"Se corrige con el marcador final.","category":"cerrado","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"both_gte","n":3},{"op":"margin_lte","n":2}]},"priority":0,"cooldown":2,"tags":["cerrado"]},{"code":"ONE_RUN_BOTH","title":"¿Los dos anotan y el final se decide por una?","description":"Se corrige con el marcador final.","category":"cerrado","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"both_gte","n":1},{"op":"margin_eq","n":1}]},"priority":0,"cooldown":2,"tags":["cerrado"]},{"code":"CLOSED_HIGH","title":"¿Habrá 9 o más carreras con diferencia de 3 o menos?","description":"Se corrige con el marcador final.","category":"cerrado","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"total_gte","n":9},{"op":"margin_lte","n":3}]},"priority":0,"cooldown":2,"tags":["cerrado"]},{"code":"OPEN_WINNER7","title":"¿El ganador llega a 7 con ventaja de 4 o más?","description":"Se corrige con el marcador final.","category":"abierto","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"winner_gte","n":7},{"op":"margin_gte","n":4}]},"priority":0,"cooldown":2,"tags":["abierto"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;